using System.IO;using ErganiManager.Licensing;namespace SPharmacyLog.UI.Services;public static class PharmacyLicenseManager{private const string PublicKey="MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEpIxMdxFQxnAp05RnSUvz3QQLGM/tBN59Vaodo90akm3+JJSqV3108cCDq06rMELHSV4auuUqer0w/DhaMgyKkA==";private static string LicenseFile=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SPharmacyLog","license.key");public static string PcCode=>MachineCode.Get();public static LicenseResult Result{get;private set;}=new(LicenseCheck.Missing,null);public static bool Load(){if(!LicenseKeys.IsConfigured){Result=new(LicenseCheck.Valid,null);return true;}string? key=null;try{if(File.Exists(LicenseFile))key=File.ReadAllText(LicenseFile);}catch{}Result=LicenseCodec.Evaluate(key,LicenseKeys.PublicKeyBase64,PcCode,DateOnly.FromDateTime(DateTime.Today));if(Result.IsValid&&!IsPharmacyModule(Result))Result=new(LicenseCheck.ModuleNotLicensed,Result.Payload);return Result.IsValid;}private static bool IsPharmacyModule(LicenseResult result)=>result.Payload?.Modules.Contains(LicenseModules.All)==true||result.Payload?.Modules.Contains(LicenseModules.SPharmacyLog,StringComparer.OrdinalIgnoreCase)==true;public static LicenseResult Activate(string? key){var r=LicenseCodec.Evaluate(key,LicenseKeys.PublicKeyBase64,PcCode,DateOnly.FromDateTime(DateTime.Today));if(r.IsValid&&!IsPharmacyModule(r))r=new(LicenseCheck.ModuleNotLicensed,r.Payload);if(r.IsValid){Directory.CreateDirectory(Path.GetDirectoryName(LicenseFile)!);File.WriteAllText(LicenseFile,LicenseCodec.Clean(key));Result=r;}return r;}}